tests/overlap_test.sh.text:
#!/bin/bash
fail=0
f=$(mktemp); : > "$f"
export BOOKINGS=$f
bash bin/book A 0900 1000 one >/dev/null
# overlapping: must fail, must not write
for r in "A 0930 1030" "A 0800 0901" "A 0930 0940" "A 0800 1100"; do
  bash bin/book $r x >/dev/null 2>&1 && { echo "overlap accepted: $r"; fail=1; }
done
[ "$(wc -l < "$f")" -eq 1 ] || { echo "file changed by rejected booking"; fail=1; }
# adjacent and other room: allowed
bash bin/book A 1000 1100 two >/dev/null || { echo "adjacent after rejected"; fail=1; }
bash bin/book A 0800 0900 zero >/dev/null || { echo "adjacent before rejected"; fail=1; }
bash bin/book B 0900 1000 other >/dev/null || { echo "other room rejected"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "expected 4 lines"; fail=1; }
rm -f "$f"
exit $fail

